import { WINES } from "./wines";

export type AlcoholCategory = "Light Beer" | "IPA & Craft Ale" | "Lager" | "Hard Seltzer" | "Cider" | "Non-Alcoholic" | "Wines";
export type WineSubcategory = "Red" | "White" | "Rosé" | "Sparkling" | "Sweet" | "Icewine";

export const ALCOHOL_CATEGORIES: AlcoholCategory[] = ["Light Beer", "IPA & Craft Ale", "Lager", "Hard Seltzer", "Cider", "Non-Alcoholic", "Wines"];

export type AlcoholRankingProduct = {
  id: string;
  category: AlcoholCategory;
  brand: string;
  name: string;
  /** Optional so PARTIAL wines (ABV pending) can omit it — never fabricate. */
  abv?: number;
  /** Optional so PARTIAL wines (ABV/sugar pending) can omit them — never fabricate. */
  caloriesPerCan?: number;
  carbsPerCan?: number;
  sugarPerCan?: number;
  knownAdditives: string[];
  additiveCount: number;
  /** 1--5 -- how fitness-friendly this drink is to reach for regularly. */
  gorillaPour: number;
  availability: string;
  /** Serving size in mL (default 355 for standard cans, 341 for longnecks, etc.). */
  servingMl?: number;
  barcodes?: string[];
  lcboVerified?: boolean;
  /** True when nutrition data is estimated from ABV + style formula rather than verified from label. */
  nutritionEstimated?: boolean;
  /** True for London Ontario brewery products -- shown with LONDON ON badge. */
  londonOntario?: boolean;
  /** True for Ontario independent craft breweries. */
  ontarioCraft?: boolean;
  /** Beer style tag for sub-category filtering (e.g. "Stout", "IPA", "Pilsner"). */
  beerStyle?: string;
  /** Wine only -- subcategory for filtering. */
  wineSubcategory?: WineSubcategory;
  /** Wine only -- grape variety or blend name. */
  varietal?: string;
  /** Wine only -- producing region. */
  region?: string;
  /** True for Ontario VQA wines (100% Ontario-grown grapes, VQA verified). */
  ontarioVQA?: boolean;
  /** VQA appellation, e.g. "Niagara Peninsula", "Prince Edward County". */
  vqaAppellation?: string;
  /** True for certified organic / biodynamic producers. */
  organicCertified?: boolean;
  /** Optional editorial writeup shown on the product card. */
  gorillaAnalysis?: string;
  /**
   * Celiac-safety tier per Health Canada/CFIA framing:
   * certified-gf = made entirely from gluten-free ingredients (celiac safe);
   * gluten-removed = barley/wheat brewed then enzyme treated (NOT celiac safe);
   * contains-gluten = standard barley/wheat product.
   */
  glutenStatus?: "certified-gf" | "gluten-removed" | "contains-gluten";
  /** True for Canadian-made certified gluten-free products — special badge. */
  canadianCertifiedGf?: boolean;
  /** City/region badge for breweries (Toronto, Hamilton, Niagara, Ottawa, Guelph, Windsor, Sarnia, …). */
  cityRegion?: string;
  /**
   * True for seltzers/RTDs sold at The Beer Store — Beer Store versions may be
   * malt-based even when the LCBO version of the same brand is spirit-based
   * with different ingredients and gluten status.
   */
  maltBasedBeerStore?: boolean;
  /** Wine only — verified critic quality score out of 100. Never fabricated; unset = UNRATED. */
  wineQuality?: number;
  /** Wine only — the critic source for wineQuality (Wine Spectator, WineAlign, etc.). */
  wineQualitySource?: string;
  /** Wine only — the vintage the critic score refers to (critic scores are vintage-specific). */
  wineVintage?: string;
  /** Wine only — source URL for the score (a stable catalogue link OR a rotating product page). */
  wineQualityUrl?: string;
  /**
   * Wine only — true ONLY when wineQualityUrl is a STABLE LCBO Vintages catalogue
   * link (lcbofoodanddrink.cld.bz). Drives the hybrid display: stable → clickable
   * proof link; non-stable product page / no URL → text attribution only. Optional —
   * when unset the card derives it from the URL, so it never has to be set by hand.
   */
  wineQualityUrlStable?: boolean;
  /** Wine only — true when the value is a competition medal/panel result, not a 100-point critic score. */
  wineScoreIsAward?: boolean;
  /** Wine only — LCBO's published residual sugar in grams per litre (stored raw). */
  sugarGPerL?: number;
  /** Bottle/format size in mL (e.g. 750, 1500, 4000). */
  bottleSizeMl?: number;
  /** LCBO catalogue number — enables an LCBO product reference. */
  lcboNumber?: string;
  /** Which market this entry's data reflects. */
  market?: "CA" | "US";
  /** LCBO sweetness descriptor: XD (extra dry) · D (dry) · M (medium) · MS (medium sweet) · S (sweet). */
  sweetnessCode?: "XD" | "D" | "M" | "MS" | "S";
  /**
   * Data confidence. "verified" = real ABV + sugar, scores normally.
   * "partial" = name/region/type known but ABV/sugar PENDING — wineGorillaScore
   * returns null and the card shows a "Score pending" state (never a fake score).
   */
  confidence?: "verified" | "partial";
};

/**
 * The wine Gorilla Score — health/nutrition per 148mL pour.
 * Sugar 40% · calorie density 30% · additives 30% (published methodology).
 */
export function wineGorillaScore(
  p: Pick<AlcoholRankingProduct, "caloriesPerCan" | "sugarPerCan" | "additiveCount" | "confidence">
): number | null {
  // PARTIAL wines (ABV/sugar pending) or any entry missing the required inputs
  // return null — the card shows "Score pending" instead of a fabricated number.
  if (p.confidence === "partial" || p.sugarPerCan === undefined || p.caloriesPerCan === undefined) {
    return null;
  }
  const sugar = p.sugarPerCan;
  const sugarScore =
    sugar <= 1 ? 95 : sugar <= 2 ? 85 : sugar <= 4 ? 70 : sugar <= 8 ? 45 : sugar <= 15 ? 20 : 5;
  const calories = p.caloriesPerCan;
  const calScore =
    calories < 115 ? 90 : calories < 125 ? 80 : calories < 135 ? 70 : calories < 145 ? 60 : calories < 155 ? 50 : calories < 165 ? 35 : 20;
  const addScore = p.additiveCount === 0 ? 100 : p.additiveCount === 1 ? 80 : p.additiveCount === 2 ? 60 : 35;
  return Math.round(sugarScore * 0.4 + calScore * 0.3 + addScore * 0.3);
}

/** GORILLA SWEET SPOT — nutritionally sound (≥70) AND critically acclaimed (≥89). */
export function isGorillaSweetSpot(p: AlcoholRankingProduct): boolean {
  const gs = wineGorillaScore(p);
  return p.wineQuality !== undefined && p.wineQuality >= 89 && gs !== null && gs >= 70;
}

